import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.rfIdp5fP.js";const g=JSON.parse('{"title":"CLI Reference","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cli.md","filePath":"guide/cli.md"}'),i={name:"guide/cli.md"};function n(d,e,r,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="cli-reference" tabindex="-1">CLI Reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI Reference&quot;">​</a></h1><p>ODDToolkit ships as a single executable JAR. You run it once per invocation, you select a generator, and the generator writes its output where your configuration file says.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/oddtoolkit.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --generator=NAME</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [OPTIONS]</span></span></code></pre></div><p>See <a href="./installation">Installation</a> if you have not built <code>target/oddtoolkit.jar</code> yet.</p><h2 id="invocation-rules" tabindex="-1">Invocation rules <a class="header-anchor" href="#invocation-rules" aria-label="Permalink to &quot;Invocation rules&quot;">​</a></h2><p>Three rules cover the whole command line:</p><ul><li><strong>There are no subcommands.</strong> <code>--generator=NAME</code> selects what runs; there is no <code>oddtoolkit generate</code> or <code>oddtoolkit run</code>.</li><li><strong>There are no positional arguments.</strong> Anything that does not start with <code>--</code> is rejected with <code>Ignoring unexpected argument: …</code> on stderr.</li><li><strong>Every option is <code>--key=value</code>.</strong> The <code>=</code> is mandatory. <code>--generator sql</code> does not work — it is parsed as a malformed option followed by a stray argument. The only exceptions are the bare help flags <code>--help</code> and <code>-h</code>.</li></ul><p>Unknown or malformed options print a warning to stderr and are then skipped. They do not stop the run.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--generator=NAME</code></td><td>Yes</td><td>Name of the generator to execute, or <code>all</code>.</td></tr><tr><td><code>--config-file=PATH</code></td><td>In practice yes</td><td>Configuration file: <code>.yml</code>, <code>.yaml</code> or <code>.json</code>.</td></tr><tr><td><code>--ontology-file=PATH</code></td><td>No</td><td>Overrides <code>ontology.ontology-file-path</code> from the configuration file.</td></tr><tr><td><code>--concepts-file=PATH</code></td><td>No</td><td>Overrides <code>ontology.concepts-file-path</code> from the configuration file.</td></tr><tr><td><code>--help</code>, <code>-h</code></td><td>No</td><td>Print the usage text and exit without running anything.</td></tr></tbody></table><p>That is the complete list. In particular there is <strong>no</strong> <code>--output</code>, <code>--output-format</code> or <code>--output-file</code> option, and no way to set arbitrary configuration properties from the command line. Output locations live in the configuration file only — see <a href="./configuration">Configuration</a>.</p><h3 id="generator-name" tabindex="-1"><code>--generator=NAME</code> <a class="header-anchor" href="#generator-name" aria-label="Permalink to &quot;`--generator=NAME`&quot;">​</a></h3><p>Selects the generator. The name is case-sensitive; <code>--generator=SQL</code> fails, <code>--generator=sql</code> works.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/oddtoolkit.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --generator=sql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --config-file=src/test/resources/application.yml</span></span></code></pre></div><p>The registered names are:</p><table tabindex="0"><thead><tr><th>Name</th><th>Produces</th></tr></thead><tbody><tr><td><code>bikeshed</code></td><td>A Bikeshed specification (<code>.bs</code>)</td></tr><tr><td><code>class</code></td><td>The in-memory class model only (no file output)</td></tr><tr><td><code>class-diagram</code></td><td>A Mermaid class diagram (<code>.mmd</code>, plus <code>.png</code> unless disabled)</td></tr><tr><td><code>data-frame</code></td><td>A data frame description (<code>.json</code>)</td></tr><tr><td><code>er-diagram</code></td><td>A Mermaid ER diagram (<code>.mmd</code>, plus <code>.png</code> unless disabled)</td></tr><tr><td><code>java</code></td><td>Java model classes in a directory</td></tr><tr><td><code>odcs</code></td><td>An Open Data Contract Standard contract (<code>.json</code>)</td></tr><tr><td><code>shacl</code></td><td>SHACL shapes in Turtle (<code>.ttl</code>)</td></tr><tr><td><code>sql</code></td><td>A SQL schema (<code>.sql</code>)</td></tr><tr><td><code>typescript</code></td><td>TypeScript model files in a directory</td></tr></tbody></table><p><code>--help</code> prints the same list, read straight from the registry, so it is always current for your build. <a href="./generators">Generators</a> documents what each one does and how to configure it.</p><h3 id="the-all-keyword" tabindex="-1">The <code>all</code> keyword <a class="header-anchor" href="#the-all-keyword" aria-label="Permalink to &quot;The `all` keyword&quot;">​</a></h3><p><code>all</code> is not a generator, it is a keyword. It runs every registered generator, in alphabetical order, in a single JVM:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/oddtoolkit.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --generator=all</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --config-file=src/test/resources/application.yml</span></span></code></pre></div><p>The match is case-insensitive, so <code>--generator=ALL</code> also works. Each generator uses its own configuration section, so a generator with no configured output path falls back to whatever that generator does by default (usually stdout). If one generator throws, the run stops there and the remaining generators do not execute.</p><h3 id="config-file-path" tabindex="-1"><code>--config-file=PATH</code> <a class="header-anchor" href="#config-file-path" aria-label="Permalink to &quot;`--config-file=PATH`&quot;">​</a></h3><p>Points at the YAML or JSON file holding the <code>ontology</code>, <code>generators</code> and <code>adapters</code> sections.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/oddtoolkit.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --generator=shacl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config-file=./my-config.yml</span></span></code></pre></div><p>The format is chosen by file extension: <code>.json</code> is parsed as JSON, <code>.yml</code> and <code>.yaml</code> as YAML. Any other extension is refused with a warning and the file is ignored. A missing file also produces a warning and is ignored — the run then continues with code defaults, which almost always fails because no ontology path is set.</p><h3 id="ontology-file-path-and-concepts-file-path" tabindex="-1"><code>--ontology-file=PATH</code> and <code>--concepts-file=PATH</code> <a class="header-anchor" href="#ontology-file-path-and-concepts-file-path" aria-label="Permalink to &quot;`--ontology-file=PATH` and `--concepts-file=PATH`&quot;">​</a></h3><p>Override the two ontology inputs without editing the configuration file. Useful for pointing the same configuration at a different ontology version.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/oddtoolkit.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --generator=class-diagram</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --config-file=src/test/resources/application.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --ontology-file=docs/examples/riepr/ontology/ns/riepr/riepr.ttl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --concepts-file=docs/examples/riepr/ontology/id/concept/riepr/riepr.ttl</span></span></code></pre></div><p>Blank values are ignored, so passing <code>--ontology-file=</code> leaves the configured value alone.</p><h3 id="help-h" tabindex="-1"><code>--help</code>, <code>-h</code> <a class="header-anchor" href="#help-h" aria-label="Permalink to &quot;`--help`, `-h`&quot;">​</a></h3><p>Both spellings work. Help wins over everything else: if <code>--help</code> appears anywhere on the command line, the usage text is printed and no generator runs.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/oddtoolkit.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><h2 id="configuration-precedence" tabindex="-1">Configuration precedence <a class="header-anchor" href="#configuration-precedence" aria-label="Permalink to &quot;Configuration precedence&quot;">​</a></h2><p>Exactly two tiers plus defaults:</p><ol><li>Command-line arguments — but only <code>--ontology-file</code> and <code>--concepts-file</code></li><li>The configuration file passed with <code>--config-file</code></li><li>Code defaults</li></ol><p>Nothing else feeds configuration. There are no <code>ODD_*</code> configuration variables, no <code>-D</code> property overrides and no implicit config file that gets picked up from the working directory.</p><h2 id="where-output-goes" tabindex="-1">Where output goes <a class="header-anchor" href="#where-output-goes" aria-label="Permalink to &quot;Where output goes&quot;">​</a></h2><p>Each generator writes to the path under its own configuration key — <code>generators.&lt;name&gt;.output-file</code> for the single-file generators, <code>generators.&lt;name&gt;.output-directory</code> for <code>java</code> and <code>typescript</code>. Parent directories are created for you.</p><p>Generators that produce a single document (<code>class-diagram</code>, <code>er-diagram</code>, <code>sql</code>, <code>shacl</code>, <code>bikeshed</code>, <code>data-frame</code>, <code>odcs</code>) print to stdout when no output path is configured, which makes them easy to pipe:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/oddtoolkit.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --generator=sql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config-file=minimal.yml</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema.sql</span></span></code></pre></div><p><code>java</code> and <code>typescript</code> have no stdout fallback: they require <code>output-directory</code> and fail without it. <code>class</code> never writes files — it only builds the in-memory model, which is useful for checking that your ontology loads.</p><h2 id="logging" tabindex="-1">Logging <a class="header-anchor" href="#logging" aria-label="Permalink to &quot;Logging&quot;">​</a></h2><p><code>ODD_LOG_LEVEL</code> is the <strong>only</strong> environment variable the toolkit reads. It sets the log level of the <code>be.vlaanderen.omgeving</code> loggers (default <code>INFO</code>); everything else logs at <code>WARN</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ODD_LOG_LEVEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DEBUG</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/oddtoolkit.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --generator=sql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --config-file=src/test/resources/application.yml</span></span></code></pre></div><p>Accepted values are the usual Logback levels: <code>TRACE</code>, <code>DEBUG</code>, <code>INFO</code>, <code>WARN</code>, <code>ERROR</code>, <code>OFF</code>. Use <code>DEBUG</code> to see each adapter as it runs. Note that <code>-Dlogging.level.*</code> does nothing here — that is Spring syntax and this project does not use Spring.</p><h2 id="jvm-options" tabindex="-1">JVM options <a class="header-anchor" href="#jvm-options" aria-label="Permalink to &quot;JVM options&quot;">​</a></h2><p>Anything before <code>-jar</code> goes to the JVM, not to the toolkit. Large ontologies mostly need heap:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Xmx4G</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/oddtoolkit.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --generator=java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --config-file=src/test/resources/application.yml</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong><code>Ignoring unexpected argument: sql</code></strong> You wrote <code>--generator sql</code> with a space, or passed a positional argument. Use <code>--generator=sql</code>.</p><p><strong><code>Unknown or malformed option: --generator (options use --key=value; run --help)</code></strong> The option had no <code>=</code>. Same fix as above.</p><p><strong><code>Unknown option: --output (run --help)</code></strong> That option does not exist. Check the table above; output paths are configured in the configuration file, not on the command line.</p><p><strong><code>No generator specified. Use --generator=NAME or --generator=all.</code></strong><code>--generator</code> is missing or empty. The help text is printed after the message and nothing runs.</p><p><strong><code>Generator &#39;sqlgenerator&#39; is not available. Available: bikeshed, class, …</code></strong> The name is not in the registry. Names are case-sensitive and match the table above — use <code>sql</code>, not <code>sqlgenerator</code> or <code>SQL</code>. The message lists the registered names.</p><p><strong><code>Configuration file not found: …</code> followed by a failure while loading the ontology</strong> The path was wrong, so the toolkit fell back to defaults and ended up with no ontology file to read. Check the path, then re-run.</p><p><strong><code>Unsupported configuration file format: … Supported: .json, .yml, .yaml</code></strong> Rename the file so its extension matches its content.</p><p><strong><code>PNG export skipped: Playwright runtime is unavailable …</code></strong> Only the PNG is missing; the <code>.mmd</code> file was written. Set <code>generators.diagram-generator.export-png: false</code> to silence it — see <a href="./installation">Installation</a>.</p>',57)])])}const k=t(i,[["render",n]]);export{g as __pageData,k as default};
